import React, { useEffect, useRef, useState } from 'react';
import { Code, Palette, Database, Globe, Smartphone, Layout, ArrowUpRight } from 'lucide-react';

const services = [
  {
    icon: Code,
    title: 'Web Development',
    description: 'Custom web applications built with modern frameworks like React.js, ensuring high performance and scalability.',
    features: ['React.js', 'Node.js', 'RESTful APIs', 'Single Page Apps'],
    gradient: 'from-blue-500 to-cyan-500',
    color: 'blue'
  },
  {
    icon: Palette,
    title: 'UI/UX Design',
    description: 'User-centered design that combines aesthetics with functionality to create intuitive digital experiences.',
    features: ['Wireframing', 'Prototyping', 'User Research', 'Design Systems'],
    gradient: 'from-purple-500 to-pink-500',
    color: 'purple'
  },
  {
    icon: Database,
    title: 'System Development',
    description: 'Robust backend systems and database solutions using PHP and MySQL for enterprise-level applications.',
    features: ['PHP', 'MySQL', 'API Integration', 'Cloud Deployment'],
    gradient: 'from-green-500 to-teal-500',
    color: 'green'
  },
  {
    icon: Globe,
    title: 'E-Commerce Solutions',
    description: 'Complete online store development with secure payment integration and inventory management.',
    features: ['Payment Gateways', 'Product Management', 'Order Tracking', 'Analytics'],
    gradient: 'from-orange-500 to-red-500',
    color: 'orange'
  },
  {
    icon: Smartphone,
    title: 'Responsive Design',
    description: 'Mobile-first approach ensuring your website looks perfect on every device and screen size.',
    features: ['Mobile-First', 'Cross-Browser', 'Fast Loading', 'SEO Ready'],
    gradient: 'from-pink-500 to-rose-500',
    color: 'pink'
  },
  {
    icon: Layout,
    title: 'Website Maintenance',
    description: 'Ongoing support and updates to keep your website secure, fast, and up-to-date with latest technologies.',
    features: ['Security Updates', 'Performance Optimization', 'Content Updates', '24/7 Support'],
    gradient: 'from-indigo-500 to-violet-500',
    color: 'indigo'
  }
];

// 3D Tilt Card Component
const TiltCard = ({ children, className }) => {
  const [transform, setTransform] = useState('');
  const cardRef = useRef(null);

  const handleMouseMove = (e) => {
    if (!cardRef.current) return;
    const rect = cardRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const centerX = rect.width / 2;
    const centerY = rect.height / 2;
    const rotateX = (y - centerY) / 20;
    const rotateY = (centerX - x) / 20;
    setTransform(`perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale3d(1.02, 1.02, 1.02)`);
  };

  const handleMouseLeave = () => {
    setTransform('perspective(1000px) rotateX(0deg) rotateY(0deg) scale3d(1, 1, 1)');
  };

  return (
    <div
      ref={cardRef}
      className={className}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      style={{ transform, transition: 'transform 0.3s ease' }}
    >
      {children}
    </div>
  );
};

const Services = () => {
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('active');
          }
        });
      },
      { threshold: 0.1, rootMargin: '0px 0px -50px 0px' }
    );

    const reveals = sectionRef.current?.querySelectorAll('.reveal');
    reveals?.forEach((el) => observer.observe(el));

    return () => observer.disconnect();
  }, []);

  return (
    <section id="services" ref={sectionRef} className="py-24 bg-[#0a1628] relative overflow-hidden">
      {/* Background elements */}
      <div className="absolute -bottom-40 -left-40 w-96 h-96 bg-blue-500/5 rounded-full blur-3xl"></div>
      <div className="absolute top-20 right-0 w-80 h-80 bg-purple-500/5 rounded-full blur-3xl"></div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Section Header */}
        <div className="text-center mb-16 reveal">
          <span className="inline-block px-4 py-2 rounded-full bg-blue-500/10 text-blue-400 text-sm font-medium mb-4">
            What We Do
          </span>
          <h2 className="text-4xl sm:text-5xl font-bold text-white mb-6">
            Our <span className="gradient-text">Services</span>
          </h2>
          <p className="text-gray-400 max-w-2xl mx-auto text-lg">
            We offer comprehensive web solutions tailored to meet your business needs 
            and help you succeed in the digital landscape.
          </p>
        </div>

        {/* Services Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {services.map((service, index) => (
            <div
              key={service.title}
              className="reveal group relative"
              style={{ transitionDelay: `${index * 100}ms` }}
            >
              <TiltCard className="h-full">
                <div className="card-minimal rounded-2xl p-8 h-full flex flex-col relative overflow-hidden">
                  {/* Number indicator */}
                  <div className="absolute top-6 right-6 text-6xl font-black text-white/5 group-hover:text-white/10 transition-colors">
                    {String(index + 1).padStart(2, '0')}
                  </div>

                  {/* Icon */}
                  <div className="w-14 h-14 rounded-xl bg-blue-600 flex items-center justify-center mb-6 transform group-hover:scale-110 transition-all duration-300 relative z-10">
                    <service.icon className="w-7 h-7 text-white" />
                  </div>

                  {/* Content */}
                  <h3 className="text-xl font-bold text-white mb-3 group-hover:text-blue-400 transition-colors relative z-10">
                    {service.title}
                  </h3>
                  <p className="text-gray-400 mb-6 leading-relaxed flex-grow text-sm relative z-10">
                    {service.description}
                  </p>

                  {/* Features */}
                  <div className="flex flex-wrap gap-2 relative z-10">
                    {service.features.slice(0, 3).map((feature) => (
                      <span
                        key={feature}
                        className={`px-3 py-1 rounded-full text-xs font-medium bg-${service.color}-500/10 text-${service.color}-400 border border-${service.color}-500/20`}
                      >
                        {feature}
                      </span>
                    ))}
                  </div>

                  {/* Hover gradient overlay */}
                  <div className={`absolute inset-0 bg-gradient-to-br ${service.gradient} opacity-0 group-hover:opacity-5 transition-opacity duration-500`}></div>

                  {/* Arrow icon */}
                  <div className="absolute bottom-6 right-6 w-10 h-10 rounded-full glass flex items-center justify-center opacity-0 group-hover:opacity-100 transform translate-y-4 group-hover:translate-y-0 transition-all duration-300">
                    <ArrowUpRight className="w-5 h-5 text-white" />
                  </div>
                </div>
              </TiltCard>
            </div>
          ))}
        </div>

        {/* CTA */}
        <div className="text-center mt-16 reveal">
          <p className="text-gray-400 mb-6">
            Need a custom solution? Let&apos;s discuss your project requirements.
          </p>
          <a
            href="#contact"
            className="inline-flex items-center gap-2 px-8 py-4 bg-blue-600 text-white font-semibold rounded-full hover:bg-blue-500 transition-all duration-300"
          >
            Get a Free Consultation
          </a>
        </div>
      </div>
    </section>
  );
};

export default Services;
